(function(){
'use strict';
var KEY='welog-pair-sheet-v4',DB='welog-mobile-fonts-v1',STORE='fonts';
var controls=document.getElementById('controls'),sheet=document.getElementById('sheet');
var uploaded=[];
function read(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch(e){return{}}}
function write(s){try{localStorage.setItem(KEY,JSON.stringify(s));return true}catch(e){return false}}
function setPath(path,value){var s=read(),p=path.split('.'),o=s;p.slice(0,-1).forEach(function(k){if(!o[k]||typeof o[k]!=='object')o[k]={};o=o[k]});o[p[p.length-1]]=value;write(s);renderNames();applyFont()}
function esc(v){var d=document.createElement('div');d.textContent=v==null?'':String(v);return d.innerHTML}
function currentSide(){var b=controls&&controls.querySelector('[data-character-side].on');return b?b.dataset.characterSide:'left'}
function openDB(){return new Promise(function(ok,no){if(!window.indexedDB){ok(null);return}var r=indexedDB.open(DB,1);r.onupgradeneeded=function(){if(!r.result.objectStoreNames.contains(STORE))r.result.createObjectStore(STORE,{keyPath:'name'})};r.onsuccess=function(){ok(r.result)};r.onerror=function(){no(r.error)}})}
function allFonts(){return openDB().then(function(db){if(!db)return[];return new Promise(function(ok,no){var r=db.transaction(STORE,'readonly').objectStore(STORE).getAll();r.onsuccess=function(){ok(r.result||[])};r.onerror=function(){no(r.error)}})})}
function putFont(x){return openDB().then(function(db){if(!db)throw new Error('IndexedDB unavailable');return new Promise(function(ok,no){var tx=db.transaction(STORE,'readwrite');tx.objectStore(STORE).put(x);tx.oncomplete=ok;tx.onerror=function(){no(tx.error)}})})}
function loadFont(x){if(!x||!x.data||!window.FontFace)return Promise.resolve();try{var f=new FontFace(x.name,x.data);return f.load().then(function(face){document.fonts.add(face);if(uploaded.indexOf(x.name)<0)uploaded.push(x.name)})}catch(e){return Promise.resolve()}}
function fontStack(name){if(!name||name==='__default__'||name==='Pretendard')return 'Pretendard,"Noto Sans KR",sans-serif';if(name==='__system__')return 'system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI","Apple SD Gothic Neo","Noto Sans KR",sans-serif';return '"'+String(name).replace(/"/g,'')+'","Noto Sans KR",sans-serif'}
function applyFont(){if(!sheet)return;var s=read(),stack=fontStack(s.font);document.documentElement.style.setProperty('--app-font',stack);document.documentElement.style.setProperty('--welog-font',stack);sheet.style.setProperty('font-family',stack,'important');sheet.querySelectorAll('*').forEach(function(el){if(!el.classList.contains('profile-symbol'))el.style.setProperty('font-family',stack,'important')})}
function ensureFontControls(){if(!controls)return;var box=controls.querySelector('.global-font-controls');if(!box)return;var sel=box.querySelector('select[data-path="font"]');if(sel){var items=[['__default__','기본 폰트 · Pretendard'],['__system__','시스템 폰트']];items.concat(uploaded.map(function(n){return[n,'업로드 · '+n]})).forEach(function(x){if(!Array.from(sel.options).some(function(o){return o.value===x[0]})){var op=document.createElement('option');op.value=x[0];op.textContent=x[1];sel.appendChild(op)}});var s=read(),v=s.font||'__default__';if(v==='Pretendard')v='__default__';if(Array.from(sel.options).some(function(o){return o.value===v}))sel.value=v}if(!box.querySelector('[data-mobile-font-upload]')){var label=document.createElement('label');label.className='mobile-font-upload';label.innerHTML='<span>폰트 업로드</span><b>TTF · OTF · WOFF · WOFF2</b><input type="file" data-mobile-font-upload accept=".ttf,.otf,.woff,.woff2,font/ttf,font/otf,font/woff,font/woff2">';box.appendChild(label)}}
function ensurePairControls(){if(!controls||!controls.querySelector('.layout-ratio-controls'))return;var old=controls.querySelector('.mobile-pair-editor');if(old)return;var s=read(),box=document.createElement('section');box.className='mobile-pair-editor';box.innerHTML='<div class="mobile-editor-head"><b>페어명</b><span>기존 상단 페어명 영역을 편집합니다.</span></div><label><span>페어명</span><input type="text" data-mobile-path="pairName" value="'+esc(s.pairName||'')+'" placeholder="페어명을 입력해 주세요."></label><label><span>페어명 별도 표기</span><input type="text" data-mobile-path="catchphrase" value="'+esc(s.catchphrase||'')+'" placeholder="페어명 아래 작은 표기"></label>';controls.querySelector('.layout-ratio-controls').insertAdjacentElement('beforebegin',box)}
function ensureCharacterControls(){if(!controls||!controls.querySelector('.character-switch'))return;var side=currentSide(),old=controls.querySelector('.mobile-character-editor');if(old&&old.dataset.side===side)return;if(old)old.remove();var first=controls.querySelector('.rich-control');if(!first)return;var d=(read()[side]||{}),box=document.createElement('section');box.className='mobile-character-editor';box.dataset.side=side;box.innerHTML='<label><span>이름 외 별도 표기</span><input type="text" data-mobile-path="'+side+'.subtitle" value="'+esc(d.subtitle||'')+'" placeholder="이름 아래에 표시할 문구"></label><label class="mobile-subtitle-color"><span>색상</span><input type="color" data-mobile-path="'+side+'.subtitleColor" value="'+esc(d.subtitleColor||'#918d86')+'"></label>';first.insertAdjacentElement('afterend',box)}
function removeDuplicatePair(){if(!sheet)return;sheet.querySelectorAll('.mobile-pair-title,.pair-title-display').forEach(function(n){n.remove()})}
function renderNames(){if(!sheet)return;removeDuplicatePair();var s=read();['left','right'].forEach(function(side){var title=sheet.querySelector('.profile.'+side+' .profile-title');if(!title)return;var name=title.querySelector(':scope > b'),stack=title.querySelector('.mobile-name-stack');if(!stack){stack=document.createElement('div');stack.className='mobile-name-stack';if(name){name.replaceWith(stack);stack.appendChild(name)}else{var existing=title.querySelector('.profile-name-stack');if(existing){existing.classList.add('mobile-name-stack');stack=existing}}}if(!stack)return;var sm=stack.querySelector('.mobile-name-subtitle');if(!sm){sm=document.createElement('small');sm.className='mobile-name-subtitle';stack.appendChild(sm)}var d=s[side]||{};sm.textContent=d.subtitle||'';sm.style.color=d.subtitleColor||'#918d86';sm.hidden=!d.subtitle})}
function ensure(){ensurePairControls();ensureCharacterControls();ensureFontControls();renderNames();applyFont()}
if(controls){controls.addEventListener('input',function(e){var p=e.target.dataset.mobilePath;if(p){setPath(p,e.target.value);return}if(e.target.matches('select[data-path="font"]')){var v=e.target.value,s=read();s.font=v;write(s);setTimeout(applyFont,0)}},true);controls.addEventListener('change',function(e){if(e.target.dataset.mobileFontUpload!==undefined){var file=e.target.files&&e.target.files[0];if(!file)return;var reader=new FileReader();reader.onload=function(){var name=(file.name||'Custom Font').replace(/\.[^.]+$/,''),data=reader.result,face;try{face=new FontFace(name,data)}catch(err){alert('이 폰트 파일을 읽을 수 없습니다.');return}face.load().then(function(f){document.fonts.add(f);if(uploaded.indexOf(name)<0)uploaded.push(name);return putFont({name:name,data:data})}).then(function(){var s=read();s.font=name;write(s);ensureFontControls();var sel=controls.querySelector('select[data-path="font"]');if(sel)sel.value=name;applyFont()}).catch(function(){alert('폰트를 불러오지 못했습니다.')})};reader.readAsArrayBuffer(file);e.target.value=''}else if(e.target.matches('select[data-path="font"]')){var s=read();s.font=e.target.value;write(s);setTimeout(applyFont,0)}},true)}
document.addEventListener('click',function(){setTimeout(ensure,0)},true);document.addEventListener('input',function(e){if(!e.target.dataset.mobilePath)setTimeout(function(){renderNames();applyFont()},0)},true);window.addEventListener('load',function(){setTimeout(ensure,50)});allFonts().then(function(list){return Promise.all(list.map(loadFont))}).catch(function(){}).then(ensure);setTimeout(ensure,0);
})();